import { useCallback, useEffect, useMemo, useState } from 'react';
import {
  readBridgeExperienceVisibility,
  type BridgeExperienceId,
} from './bridgeExperienceVisibility';
import { SHOW_ASSISTANT_EXPERIENCE } from '../components/IaPlaceholder/assistantIaTrial';
import { isExperienceSetup } from './experienceSetup';

/** Prototype IA models — switch to compare side by side. */
export type NavIaModel =
  | 'curated'
  | 'experiences'
  | 'flat'
  | 'hybrid'
  | 'homeband';

/**
 * Experiences for Option 5 (toggle). Availability depends on seat + plugins.
 * Templates/Activity are duplicated inside each experience's rail.
 *
 * Develop is one experience (nested Content rail: Git Repositories · Content quality).
 * Legacy ids `develop-tabs` / `develop-drawer` / `develop-apme` normalize to `develop`.
 */
export type NavExperience =
  | 'all'
  | 'automate'
  | 'develop'
  | 'compliance'
  | 'edge'
  | 'orchestrator'
  | 'assistant'
  | 'admin';

const MODEL_KEY = 'portal-nav-ia-model';
const EXPERIENCE_KEY = 'portal-nav-experience';

/** Default for Experiences shell branch — Bridge + experience rails (not Opt 1–5 bakeoff). */
const DEFAULT_MODEL: NavIaModel = 'experiences';
const DEFAULT_EXPERIENCE: NavExperience = 'all';

const listeners = new Set<() => void>();

function notify() {
  listeners.forEach(fn => fn());
}

function readModel(): NavIaModel {
  // Experiences shell branch: always experiences (ignore leftover bakeoff localStorage).
  try {
    const raw = localStorage.getItem(MODEL_KEY);
    if (raw && raw !== 'experiences') {
      localStorage.setItem(MODEL_KEY, 'experiences');
    }
  } catch {
    /* ignore */
  }
  return DEFAULT_MODEL;
}

function normalizeExperience(raw: string | null): NavExperience | null {
  if (
    raw === 'all' ||
    raw === 'automate' ||
    raw === 'develop' ||
    raw === 'compliance' ||
    raw === 'edge' ||
    raw === 'orchestrator' ||
    (SHOW_ASSISTANT_EXPERIENCE && raw === 'assistant') ||
    raw === 'admin'
  ) {
    return raw;
  }
  if (raw === 'assistant') {
    try {
      localStorage.setItem(EXPERIENCE_KEY, 'all');
    } catch {
      /* ignore */
    }
    return 'all';
  }
  // Killed APME A/B ids + older Develop labels → one Develop experience
  if (
    raw === 'develop-tabs' ||
    raw === 'develop-drawer' ||
    raw === 'develop-apme' ||
    raw === 'develop-section'
  ) {
    try {
      localStorage.setItem(EXPERIENCE_KEY, 'develop');
    } catch {
      /* ignore */
    }
    return 'develop';
  }
  return null;
}

function readExperience(): NavExperience {
  try {
    return normalizeExperience(localStorage.getItem(EXPERIENCE_KEY)) ?? DEFAULT_EXPERIENCE;
  } catch {
    return DEFAULT_EXPERIENCE;
  }
}

export function writeNavIaModel(model: NavIaModel) {
  localStorage.setItem(MODEL_KEY, model);
  notify();
}

export function writeNavExperience(experience: NavExperience) {
  localStorage.setItem(EXPERIENCE_KEY, experience);
  notify();
}

/** Develop experience (nested Content rail: Git Repositories · Content quality). */
export function isDevelopExperience(experience: NavExperience): boolean {
  return experience === 'develop';
}

/** Nested rail: Git Repositories + Content quality (page tabs: Overview / Remediations / Scans). */
export function isDevelopReposRailMode(experience: NavExperience): boolean {
  return experience === 'develop';
}

export function availableExperiences(args: {
  role: string;
  isAdmin: boolean;
  compliance: boolean;
  rhem: boolean;
  /**
   * @deprecated Automate is always an experience. Kept for call-site compat; ignored.
   */
  includeAutomate?: boolean;
  /** Admin “On Bridge” toggles. Omit to read the persisted prototype store. */
  bridgeVisibility?: Record<BridgeExperienceId, boolean>;
}): NavExperience[] {
  // SME locked to Automate (no Bridge).
  if (args.role === 'sme') {
    return ['automate'];
  }
  const vis = args.bridgeVisibility ?? readBridgeExperienceVisibility();
  const list: NavExperience[] = ['all'];
  if (vis.automate) {
    list.push('automate');
  }
  if ((args.role === 'developer' || args.isAdmin) && vis.develop) {
    list.push('develop');
  }
  if (
    (args.role === 'operator' || args.isAdmin) &&
    args.compliance &&
    vis.compliance
  ) {
    list.push('compliance');
  }
  if ((args.role === 'operator' || args.isAdmin) && args.rhem && vis.edge) {
    list.push('edge');
  }
  if (
    isExperienceSetup('orchestrator') &&
    vis.orchestrator &&
    (args.role === 'developer' || args.isAdmin)
  ) {
    list.push('orchestrator');
  }
  if (SHOW_ASSISTANT_EXPERIENCE) {
    list.push('assistant');
  }
  if (args.isAdmin) list.push('admin');
  return list;
}

export const EXPERIENCE_LABELS: Record<NavExperience, string> = {
  all: 'Experiences',
  automate: 'Automate',
  develop: 'Develop',
  compliance: 'Compliance',
  edge: 'Edge',
  orchestrator: 'Orchestrator',
  assistant: 'Assistant',
  admin: 'Administration',
};

/** Path owns Admin + Assistant so the switcher label matches the rail. */
export function experienceFromPath(pathname: string): NavExperience | null {
  if (
    pathname === '/self-service/orchestrator' ||
    pathname.startsWith('/self-service/orchestrator/')
  ) {
    return 'orchestrator';
  }
  if (
    pathname.startsWith('/self-service/admin') ||
    pathname === '/rbac' ||
    pathname.startsWith('/rbac/')
  ) {
    return 'admin';
  }
  if (
    SHOW_ASSISTANT_EXPERIENCE &&
    (pathname === '/self-service/assistant' ||
      pathname.startsWith('/self-service/assistant/'))
  ) {
    return 'assistant';
  }
  return null;
}

/** Shared across header + sidebar so IA model / experience stay in sync. */
export function useNavIaModel() {
  const [model, setModelState] = useState<NavIaModel>(readModel);
  const [experience, setExperienceState] = useState<NavExperience>(readExperience);

  useEffect(() => {
    const sync = () => {
      setModelState(readModel());
      setExperienceState(readExperience());
    };
    listeners.add(sync);
    return () => {
      listeners.delete(sync);
    };
  }, []);

  const setModel = useCallback((next: NavIaModel) => {
    localStorage.setItem(MODEL_KEY, next);
    setModelState(next);
    notify();
  }, []);

  const setExperience = useCallback((next: NavExperience) => {
    localStorage.setItem(EXPERIENCE_KEY, next);
    setExperienceState(next);
    notify();
  }, []);

  return useMemo(
    () => ({ model, setModel, experience, setExperience }),
    [model, setModel, experience, setExperience],
  );
}
